import itertools

# Label vertices as 2-subsets of {0,1,2,3,4}
vertices = list(itertools.combinations(range(5), 2))
print("Vertices:", vertices)

# Map subset to index
index = {v:i for i,v in enumerate(vertices)}

# Generate edges for complement of Petersen (intersection graph)
edges = []
for i in range(len(vertices)):
    for j in range(i+1, len(vertices)):
        # edge if subsets intersect
        if set(vertices[i]) & set(vertices[j]):
            edges.append((i, j))

print("Number of edges:", len(edges))
print("Edges:", edges)

# Check independence number: maximum set of vertices with no edges among them
# In this graph, independent set = set of pairwise disjoint 2-subsets = matching in K_5
# Max matching in K_5 is 2, so alpha should be 2.
# Let's brute force to verify.
max_ind = 0
max_sets = []
for r in range(1, len(vertices)+1):
    for subset in itertools.combinations(range(len(vertices)), r):
        ok = True
        for i, j in itertools.combinations(subset, 2):
            if (i, j) in edges or (j, i) in edges:
                # since edges only stored i<j, check
                if (min(i,j), max(i,j)) in edges:
                    ok = False
                    break
        if ok:
            if r > max_ind:
                max_ind = r
                max_sets = [subset]
            elif r == max_ind:
                max_sets.append(subset)
    if max_ind < r:
        break

print("Independence number:", max_ind)
print("Example max independent sets:", max_sets[:5])

# Check vertex connectivity by brute force (naive)
def is_connected(n, edge_set):
    # BFS from vertex 0
    visited = [False]*n
    stack = [0]
    visited[0] = True
    while stack:
        u = stack.pop()
        for v in range(n):
            if u == v: continue
            if (min(u,v), max(u,v)) in edge_set:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
    return all(visited)

# Convert edges to set for fast lookup
edge_set = set(edges)
print("Graph connected?", is_connected(10, edge_set))

# Compute vertex connectivity
kappa = 10
for k in range(1, 10):
    found_cut = False
    for cut in itertools.combinations(range(10), k):
        remaining = [v for v in range(10) if v not in cut]
        if len(remaining) == 0:
            continue
        # Build edge set on remaining vertices
        rem_edge_set = set()
        for e in edges:
            if e[0] not in cut and e[1] not in cut:
                rem_edge_set.add(e)
        # Check if induced subgraph on remaining is connected
        # BFS from remaining[0]
        if not remaining:
            continue
        visited = {v: False for v in remaining}
        stack = [remaining[0]]
        visited[remaining[0]] = True
        while stack:
            u = stack.pop()
            for v in remaining:
                if u == v: continue
                if (min(u,v), max(u,v)) in rem_edge_set:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
        if not all(visited[v] for v in remaining):
            found_cut = True
            break
    if found_cut:
        kappa = k
        break
    else:
        # no cut of size k
        pass

print("Vertex connectivity:", kappa)
